<!doctype html><html lang="en"><head>@include('partials.pyrosense-favicon')<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AAR Signature Verification</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;box-sizing:border-box;background:#f4f7fb;color:#172033;font-family:Inter,system-ui,sans-serif}.card{width:min(620px,100%);background:#fff;border:1px solid #dfe6ee;border-radius:24px;padding:28px;box-shadow:0 18px 45px rgba(15,23,42,.08)}.status{padding:14px;border-radius:14px;font-weight:800;background:{{ $valid ? '#e9f8ef' : '#fff0f0' }};color:{{ $valid ? '#187447' : '#a52f2f' }}}h1{margin:18px 0 7px;font-size:1.55rem}.muted{color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}.item{padding:13px;background:#f7f9fc;border-radius:12px}.item span{display:block;color:#64748b;font-size:.72rem;text-transform:uppercase;letter-spacing:.06em}.item strong{display:block;margin-top:5px}.code{margin-top:18px;font-family:monospace;font-size:.72rem;overflow-wrap:anywhere}@media(max-width:550px){.grid{grid-template-columns:1fr}}</style></head><body><main class="card"><div class="status">{{ $valid ? '✓ Valid digitally approved AAR' : '✕ Verification failed' }}</div><h1>{{ $report->activity_title }}</h1><div class="muted">AAR #{{ $report->after_activity_report_id }} · {{ $report->station?->station_name ?: 'Station not recorded' }}</div><div class="grid"><div class="item"><span>Activity date</span><strong>{{ optional($report->activity_date)->format('d F Y') }}</strong></div><div class="item"><span>Review status</span><strong>{{ str($report->review_status)->replace('_',' ')->title() }}</strong></div><div class="item"><span>Prepared by</span><strong>{{ $report->preparedBy?->user?->full_name ?: 'Not recorded' }}</strong></div><div class="item"><span>Approved by</span><strong>{{ $report->approval_signer_name ?: 'Not approved' }}</strong></div><div class="item"><span>Signed at</span><strong>{{ optional($report->approved_signed_at)->format('d M Y, g:i A') ?: 'Not signed' }}</strong></div><div class="item"><span>Integrity check</span><strong>{{ $valid ? 'Report contents match signature' : 'Signature or contents do not match' }}</strong></div></div><div class="code">Signature: {{ $report->approval_signature_hash ?: 'None' }}</div></main></body></html>
